PRAGMA foreign_keys=ON;
CREATE TABLE student (student_id TEXT NOT NULL, name TEXT NOT NULL, date_of_birth TEXT NOT NULL, phone_number TEXT NOT NULL, home_address TEXT NOT NULL, registration_eligibility TEXT NOT NULL CHECK(registration_eligibility IN ('ELIGIBLE','INELIGIBLE')), class TEXT NOT NULL, major TEXT NOT NULL, PRIMARY KEY (student_id));
CREATE TABLE course (course_id TEXT NOT NULL, course_name TEXT NOT NULL, credits INTEGER NOT NULL CHECK(credits > 0), instructor TEXT NOT NULL, class_time TEXT NOT NULL, class_location TEXT NOT NULL, course_offering_proposed_at TEXT, course_offering_approved_at TEXT, course_offering_published_at TEXT, course_offering_closed_at TEXT, PRIMARY KEY (course_id));
CREATE TABLE registration (student_id TEXT NOT NULL, course_id TEXT NOT NULL, registration_time TEXT NOT NULL, status TEXT NOT NULL CHECK(status='REGISTERED'), registration_requested_at TEXT, registration_approved_at TEXT, course_started_at TEXT, course_assessment_completed_at TEXT, course_grade_finalized_at TEXT, PRIMARY KEY (student_id,course_id), FOREIGN KEY (student_id) REFERENCES student(student_id), FOREIGN KEY (course_id) REFERENCES course(course_id));
CREATE TABLE degree_examination_result (result_id TEXT NOT NULL, student_id TEXT NOT NULL, examination_name TEXT NOT NULL, grade INTEGER NOT NULL CHECK(grade BETWEEN 0 AND 100), examination_date TEXT NOT NULL, examination_scheduled_at TEXT, examination_checked_in_at TEXT, examination_score_published_at TEXT, examination_result_reviewed_at TEXT, PRIMARY KEY (result_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE task (task_id TEXT NOT NULL, task_title TEXT NOT NULL, task_description TEXT NOT NULL, task_start_date TEXT NOT NULL, task_end_date TEXT NOT NULL, task_location TEXT NOT NULL, design_task_created_at TEXT, design_task_approved_at TEXT, design_task_published_at TEXT, design_task_closed_at TEXT, PRIMARY KEY (task_id));
CREATE TABLE simulation_module (module_id TEXT NOT NULL, module_name TEXT NOT NULL, module_type TEXT NOT NULL, module_description TEXT NOT NULL, module_code TEXT NOT NULL, simulation_module_published_at TEXT, simulation_module_validated_at TEXT, simulation_module_released_at TEXT, simulation_module_retired_at TEXT, PRIMARY KEY (module_id));
CREATE TABLE thesis (thesis_id TEXT NOT NULL, student_id TEXT NOT NULL, thesis_title TEXT NOT NULL, thesis_content TEXT NOT NULL, submission_date TEXT NOT NULL, thesis_draft_registered_at TEXT, thesis_review_started_at TEXT, thesis_accepted_at TEXT, thesis_revision_requested_at TEXT, thesis_resubmitted_at TEXT, PRIMARY KEY (thesis_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE student_simulation_experiment_result (student_id TEXT NOT NULL, module_id TEXT NOT NULL, simulation_date TEXT NOT NULL, simulation_result_data TEXT NOT NULL, result_analysis TEXT NOT NULL, simulation_run_scheduled_at TEXT, simulation_run_started_at TEXT, simulation_output_reviewed_at TEXT, simulation_result_accepted_at TEXT, PRIMARY KEY (student_id,module_id,simulation_date), FOREIGN KEY (student_id) REFERENCES student(student_id), FOREIGN KEY (module_id) REFERENCES simulation_module(module_id));
CREATE TABLE assignment (assignment_id TEXT NOT NULL, student_id TEXT NOT NULL, assignment_content TEXT NOT NULL, assignment_assigned_at TEXT, assignment_submitted_at TEXT, assignment_grade_finalized_at TEXT, assignment_revision_requested_at TEXT, assignment_resubmitted_at TEXT, PRIMARY KEY (assignment_id), FOREIGN KEY (student_id) REFERENCES student(student_id));
CREATE TABLE instructor (instructor_id TEXT NOT NULL, instructor_name TEXT NOT NULL, course TEXT NOT NULL, PRIMARY KEY (instructor_id));
CREATE TABLE assignment_grading (assignment_id TEXT NOT NULL, instructor_id TEXT NOT NULL, grading_time TEXT NOT NULL, score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), evaluation TEXT NOT NULL, grading_kind TEXT NOT NULL DEFAULT 'ORIGINAL' CHECK(grading_kind IN ('ORIGINAL','REASSESSMENT')), reassessment_event_id TEXT, PRIMARY KEY (assignment_id,instructor_id,grading_time), FOREIGN KEY (assignment_id) REFERENCES assignment(assignment_id), FOREIGN KEY (instructor_id) REFERENCES instructor(instructor_id));
CREATE UNIQUE INDEX ux_reassessment_event_id ON assignment_grading(reassessment_event_id);
